('vespormoor','vesper-fog-navigation','Fog navigation','Locals stop at known lamps or walls during dense fog rather than trusting a path that seems to continue.','custom','canonical','visitor','standard',null,'fog|navigation|custom','lost in fog|follow path|known lamp',5,false,null,'{}'),
('vespormoor','vesper-bells-after-dark','Bells after dark','After-dark bells distinguish fire, lost travelers, lake danger, and ordinary hours through different patterns.','local_knowledge','canonical','local','standard',null,'bell|night|safety','night bell|bell pattern|lake danger',20,false,null,'{}'),
('vespormoor','vesper-inn-discretion','Inn discretion','Innkeepers do not volunteer guest names, room companions, or late-night arrivals without a safety or legal reason.','privacy','canonical','visitor','standard',null,'inn|privacy|custom','innkeeper tell|guest room|late arrival',5,false,null,'{}'),
('vespormoor','vesper-family-crests','Old family crests','Crests on gates, books, and invitations identify family networks that still influence social access.','culture','canonical','visitor','standard','vesper-heights','family|crest|social','family crest|old family|gate symbol',5,false,null,'{}'),
('vespormoor','vesper-herbal-wards','Herbal wards','Certain door herbs are locally understood as protective requests and should not be removed by visitors.','custom','canonical','local','standard',null,'herb|ward|custom','door herbs|protective ward|remove herbs',20,false,null,'{}'),
('vespormoor','vesper-funeral-bells','Funeral bells','Funeral bells announce mourning to the town without disclosing every private circumstance of a death.','custom','canonical','visitor','standard',null,'funeral|bell|mourning','funeral bell|death announcement|mourning',5,false,null,'{}'),
('vespormoor','vesper-winter-hospitality','Winter hospitality','During severe winter weather, refusing temporary shelter is considered shameful unless a genuine safety concern exists.','custom','canonical','visitor','standard',null,'winter|shelter|custom','winter shelter|storm hospitality|take someone in',5,false,null,'{}'),
('vespormoor','vesper-night-boating','Night-boating rules','Night boating on Lake Vesper requires lights, a logged route, and conditions clear enough for shore signals.','law','canonical','public','standard','lake-vesper','boat|lake|law','night boat|lake rules|logged route',0,false,null,'{}'),
('vespormoor','vesper-parish-gaps','Parish-record gaps','Several parish registers have unexplained gaps around years of Covenant conflict and family disappearance.','history','canonical','local','standard','old-vesper','record|history|parish','missing register|church record|family disappearance',20,true,'vesper-parish-gap','{}'),
('vespormoor','vesper-old-vesper-rebuilt','Old Vesper rebuilt','Much of Old Vesper was rebuilt after the Burning Winter, often using surviving foundations and scorched stone.','history','canonical','visitor','standard','old-vesper','history|architecture|fire','old vesper rebuilt|scorched stone|1846',5,false,null,'{}'),
('vespormoor','vesper-physician-confidentiality','Physician confidentiality','Vespormoor physicians protect both ordinary medical information and Veiled conditions under strict confidentiality.','privacy','canonical','local','standard',null,'medical|veiled|privacy','doctor tell|veiled condition|medical secret',20,false,null,'{}'),
('vespormoor','vesper-invitation-names','Invitation names','A formal invitation''s exact names and titles define who is welcome; bringing an unlisted guest can be a deliberate social challenge.','custom','canonical','local','standard','vesper-heights','invitation|name|custom','plus one|formal invitation|unlisted guest',20,false,null,'{}'),
('vespormoor','vesper-lake-ice','Lake-ice taboo','Residents do not trust Lake Vesper''s ice even in prolonged cold, and crossing it is both discouraged and uncommon.','custom','canonical','visitor','standard','lake-vesper','lake|winter|safety','walk on ice|frozen lake|lake crossing',5,false,null,'{}'),
('vespormoor','vesper-returning-families','Old families returning','Members of old Covenant families have recently returned to Vespormoor after long absences.','local_knowledge','canonical','local','standard','vesper-heights','family|return|present threat','old family returns|back in town|covenant family',20,true,'vesper-family-return','{}');

insert into public.together_world_facts(
  world_id,slug,title,fact_text,category,truth_mode,knowledge_scope,content_level,location_id,
  topic_tags,trigger_terms,min_world_familiarity,interactive,event_template_slug,metadata
)
select world.id,seed.slug,seed.title,seed.fact_text,seed.category,seed.truth_mode,seed.knowledge_scope,seed.content_level,location.id,
  case when seed.tags='' then '{}'::text[] else string_to_array(seed.tags,'|') end,
  case when seed.triggers='' then '{}'::text[] else string_to_array(seed.triggers,'|') end,
  seed.min_familiarity,seed.interactive,seed.event_template_slug,seed.metadata
from kivelle_world_fact_seed seed
join public.together_worlds world on world.slug=seed.world_slug
left join public.together_locations location on location.world_id=world.id and location.slug=seed.location_slug
on conflict(world_id,slug) do update set
  title=excluded.title,fact_text=excluded.fact_text,category=excluded.category,truth_mode=excluded.truth_mode,
  knowledge_scope=excluded.knowledge_scope,content_level=excluded.content_level,location_id=excluded.location_id,
  topic_tags=excluded.topic_tags,trigger_terms=excluded.trigger_terms,min_world_familiarity=excluded.min_world_familiarity,
  interactive=excluded.interactive,event_template_slug=excluded.event_template_slug,metadata=excluded.metadata,active=true,updated_at=now();

do $$
declare target_world_slug text;fact_count integer;
begin
  foreach target_world_slug in array array['juniper-city','port-vervelle','neon-kyo','vespormoor'] loop
    select count(*) into fact_count from public.together_world_facts fact join public.together_worlds world on world.id=fact.world_id where world.slug=target_world_slug and fact.active;
    if fact_count<50 then raise exception 'World fact pack incomplete for %: %',target_world_slug,fact_count;end if;
  end loop;
end $$;
